/// <summary>
/// METCoverNoteDP class.
/// </summary>
[SrsReportParameterAttribute(classStr(METCoverNoteContract))]
public class METCoverNoteDP extends SrsReportDataProviderPreProcessTempDB
{   
    METCoverNoteContract            contract;
    METCoverNoteTotesTmp            totesTmp;
    METCoverNoteHeaderTmp           headerTmp;
    METCoverNoteSalesOrdersTmp      salesOrdersTmp;
    METCoverNoteProductTypesTmp     productTypesTmp;
    METCoverNoteTrasnferOrderTmp    transferOrderTmp;

    METBundleGuid   bundleHeaderReportGuid;
    METBundleGuid   headerReportGuid;

    const str containerTypeCodeCHP = 'CHP';
    const str containerTypeCodeLOS = 'LOS';
    const str containerTypeCodeLFT = 'LFT';
    const str containerTypeCodeBLT = 'BLT';
    const str containerTypeCodePLN = 'PLN';
    const str containerTypeCodeTOT = 'TOT';

}

Method.Source:
// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

    /// <summary>
    /// Get branding details from industry key
    /// </summary>
    /// <param name = "_industryKey">Industry Key</param>
    /// <returns>SysDocuBrandDetails</returns>
    public SysDocuBrandDetails getDocuBrandDetails(METIndustryKey _industryKey)
    {
        SysDocuBrandDetails docuBrandDetails;

        select firstonly docuBrandDetails
            where docuBrandDetails.ReportName == METConstants::METCoverNoteReport
            && docuBrandDetails.METIndustryKey == _industryKey;

        return docuBrandDetails;
    }

    /// <summary>
    /// ProcessReport
    /// </summary>
    public void processReport()
    {
        CustTable                           custTable;
        TMSCarrier                          tmsCarrier;
        SalesTable                          salesTable;
        CompanyInfo                         companyInfo;
        TMSSalesTable                       tmsSalesTable;
        InventLocation                      inventLocation;
        SysDocuBrandDetails                 docuBrandingDetails;
        METIndustryKeyTable                 industryKeyTable;
        InventTransferTable                 transferTable;
        METSalesOrderShipmentLoadLines      shipmentLines;
        METSalesOrderShipmentLoadHeader     shipmentHeader;
        METWarehouseCarrierCustomerView     whsCustomerCarrier;
        
        contract = this.parmDataContract();

        //Fetch the record from the <c>METSalesOrderShipmentLoadHeader</c>
        select firstonly CustAccount, ToWarehouse, ToWHInternalCustomer, TransactionType, Warehouse, Route, RouteStopNum, ShipmentId from shipmentHeader
            where shipmentHeader.ShipmentId == contract.parmShipmentId();

        if (shipmentHeader.RecId)
        {

            if (shipmentHeader.TransactionType == METOrderTransactionType::SalesOrder)
            {
                custTable = CustTable::find(shipmentHeader.CustAccount);
            }
            else if (shipmentHeader.TransactionType == METOrderTransactionType::TransferOrder)
            {
                custTable = CustTable::find(shipmentHeader.ToWHInternalCustomer);
            }

            select firstonly CustomerInstruction, WarehouseInstruction from whsCustomerCarrier
                where whsCustomerCarrier.CustAccount == custTable.AccountNum;

            select firstonly METDocumentNum, METRevision, METRevisionDate from companyInfo
                where companyInfo.DataArea == curExt();

            //Fetch the Industry key table record using ToWarehouse of <c>METSalesOrderShipmentLoadHeader</c>
            select firstonly RecId, Name, InventLocationId from inventLocation
                where inventLocation.InventLocationId == shipmentHeader.Warehouse
                join CompanyName, IndustryKey from industryKeyTable
                where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity;

            docuBrandingDetails = this.getDocuBrandDetails(industryKeyTable.IndustryKey);

            headerTmp.clear();

            headerTmp.IndustryKey           = industryKeyTable.IndustryKey;
            headerTmp.CompanyName           = industryKeyTable.CompanyName;

            headerTmp.PrimaryImage          = docuBrandingDetails.Image1Name;
            headerTmp.CompanyABN            = docuBrandingDetails.METTaxRegNumber;
            headerTmp.ShipmentId            = shipmentHeader.ShipmentId;
            headerTmp.PODNumber             = METCoverNoteDP::getNumberSeq();
            headerTmp.Revision              = companyInfo.METRevision;
            headerTmp.RevisionDate          = companyInfo.METRevisionDate;
            headerTmp.DocumentNumber        = companyInfo.METDocumentNum;
            headerTmp.Phone                 = docuBrandingDetails.Phone;

            headerTmp.CustomerAccountNumber = custTable.AccountNum;
            headerTmp.CustomerName          = custTable.name();
            headerTmp.CustomerAddress       = custTable.address();
            headerTmp.CustomerPhone         = custTable.phone();
            headerTmp.WareHouseInstruction  = whsCustomerCarrier.WarehouseInstruction;
            headerTmp.CustomerInstruction   = whsCustomerCarrier.CustomerInstruction;

            headerTmp.SecurityCartons       = 1;
            headerTmp.RunNumber             = strFmt("%1/%2", shipmentHeader.Route, shipmentHeader.RouteStopNum);//shipmentHeader.Route + '/' + any2Str(shipmentHeader.RouteStopNum);
            
            headerTmp.Text                  = 'KEGs';
            headerTmp.ReportDateTime        = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            headerTmp.ReportUser            = XUserInfo::find(false, curUserId()).name;

            headerTmp.WarehouseName         = inventLocation.Name;
            headerTmp.WarehouseAddress      = inventLocation.address();

            //Get the carrier code from the <c>TMSSalesTable</c>
            select firstonly CarrierCode from tmsSalesTable
                join OrderNum from shipmentLines order by OrderNum asc
                    where tmsSalesTable.SalesId == shipmentLines.OrderNum
                    && shipmentLines.ShipmentId == shipmentHeader.ShipmentId;

            tmsCarrier = TMSCarrier::find(tmsSalesTable.CarrierCode);

            headerTmp.Carrier       = tmsSalesTable.CarrierCode;
            headerTmp.CarrierName   = tmsCarrier.Name;
            headerTmp.OrderNumber   = shipmentLines.OrderNum;

            this.addContainerType(inventLocation.InventLocationId);

            headerTmp.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
            headerTmp.CoverNotesHeaderGuidStr      = headerReportGuid;

            this.insertLineData(shipmentHeader.ShipmentId, shipmentHeader.TransactionType);
            this.addContainerTable(shipmentHeader.ShipmentId);

            headerTmp.insert();
        }
    }

    /// <summary>
    /// Insert line level data.
    /// </summary>
    /// <param name = "_shipmentID">Shipment ID</param>
    public void insertLineData(MetShipmentId _shipmentID, METOrderTransactionType _transactionType)
    {
        METSalesOrderShipmentLoadLines shipmentLines;

        while select  OrderNum, ShipmentId from shipmentLines
            group by OrderNum
            where shipmentLines.ShipmentId == contract.parmShipmentId()
        {
            if (_transactionType == METOrderTransactionType::SalesOrder)
            {
                //Insert sales order id into <c>METCoverNoteSalesOrdersTmp<c/>
                salesOrdersTmp.clear();

                salesOrdersTmp.SalesId                      = shipmentLines.OrderNum;
                salesOrdersTmp.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
                salesOrdersTmp.CoverNotesHeaderGuidStr      = headerReportGuid;
                salesOrdersTmp.insert();

                this.addProductTypesSalesOrder(shipmentLines.OrderNum, shipmentLines.ShipmentId, shipmentLines.Quantity);
                this.addTotes(shipmentLines.OrderNum);
            }
            else if (_transactionType == METOrderTransactionType::TransferOrder)
            {
                //Insert sales order id into <c>METCoverNoteTrasnferOrderTmp<c/>
                transferOrderTmp.clear();

                transferOrderTmp.TransferId                 = shipmentLines.OrderNum;
                transferOrderTmp.BundleReportHeaderGuidStr  = bundleHeaderReportGuid;
                transferOrderTmp.CoverNotesHeaderGuidStr    = headerReportGuid;
                transferOrderTmp.insert();

                this.addProductTypesTransferOrder(shipmentLines.OrderNum, shipmentLines.ShipmentId);
            }
        }
    }

    /// <summary>
    /// Get the container table and insert into header tmp table.
    /// </summary>
    /// <param name = "_shipmentId"></param>
    public void addContainerTable(MetShipmentId _shipmentId)
    {
        MetContainerTable containerTable;

        while select ContainerTypeCode, ContainerQty from containerTable
            where containerTable.ShipmentId == _shipmentId
        {
            if (containerTable.ContainerTypeCode == containerTypeCodeCHP)
            {
                headerTmp.ChepPalletCount   += containerTable.ContainerQty;
                headerTmp.QuantityOut       += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeLOS)
            {
                headerTmp.LoscamPalletCount += containerTable.ContainerQty;
                headerTmp.QuantityOut       += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeLFT)
            {
                headerTmp.PalletLiftCount   += containerTable.ContainerQty;
                headerTmp.QuantityOut       += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeBLT)
            {
                headerTmp.CoolerBlanketCount    += containerTable.ContainerQty;
                headerTmp.QuantityOut           += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodePLN)
            {
                headerTmp.PlainPalletCount  += containerTable.ContainerQty;
                headerTmp.QuantityOut       += containerTable.ContainerQty;
            }
        }
    }

    /// <summary>
    /// Get the container type and insert into header tmp table.
    /// </summary>
    /// <param name = "_inventLocationId"></param>
    public void addContainerType(InventLocationId _inventLocationId)
    {
        METContainerTypeTable containerType;

        while select containerType
            where containerType.InventLocationId == _inventLocationId
        {
            if (containerType.ContainerTypeCode == containerTypeCodeCHP)
            {
                headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.ChepPalletCount * containerType.Weight);
            }
            else if (containerType.ContainerTypeCode == containerTypeCodeLOS)
            {
                headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.LoscamPalletCount * containerType.Weight);
            }
            else if (containerType.ContainerTypeCode == containerTypeCodeLFT)
            {
                headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.PalletLiftCount * containerType.Weight);
            }
            else if (containerType.ContainerTypeCode == containerTypeCodeBLT)
            {
                headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.CoolerBlanketCount * containerType.Weight);
            }
            else if (containerType.ContainerTypeCode == containerTypeCodePLN)
            {
                headerTmp.PalletContainerWeight += headerTmp.PalletContainerWeight + (headerTmp.PlainPalletCount * containerType.Weight);
            }
        }
    }

    /// <summary>
    /// Add product types for the sales order.
    /// </summary>
    /// <param name = "_salesId">Sales order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void addProductTypesSalesOrder(SalesId _salesId, MetShipmentId _shipmentId, Qty _deliveryNoteQty)
    {
        WHSFilters                  whsFilters;
        SalesLine                   salesLine;
        METSalesLine                metSalesLine;
        InventDim                   inventDim;
        MetContainerTable           containerTable;
        METInventItemOrderSetup     metInventItemOrderSetup;
        UnitOfMeasureFromRecId      fromUnit,toUnit;

        while select salesLine where salesLine.SalesId == _salesId
            join metSalesLine
                where metSalesLine.SalesLine == salesLine.RecId
            join inventDimId, InventSiteId from inventDim
                where inventDim.inventDimId == salesLine.InventDimId
            join ItemType, FilterCode from metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == salesLine.ItemId
                && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
            join whsFilters
                where whsFilters.FilterTitle == WHSFilterTitle::Code1
                && whsFilters.FilterNum == metInventItemOrderSetup.FilterCode
        {
            Factor                  factor;
            InventDim               inventDimDefaultSetting;
            InventItemSalesSetup    inventItemSalesSetup;

            select firstonly METSalesUnit from inventItemSalesSetup
                join inventDimDefaultSetting
                    where inventDimDefaultSetting.inventDimId == inventItemSalesSetup.InventDimId
                    && inventItemSalesSetup.ItemId == salesLine.ItemId
                    && inventDimDefaultSetting.InventSiteId == inventDim.InventSiteId;

            toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(salesLine.SalesUnit);
            fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventItemSalesSetup.METSalesUnit);

            factor      = EcoResProductUnitConverter::convertForReleasedProduct(
                                    salesLine.ItemId,
                                    salesLine.inventDimId,
                                    1,
                                    fromUnit,
                                    toUnit,
                                    NoYes::No,
                                    NoYes::No);

            if (factor)
            {
                productTypesTmp.clear();

                productTypesTmp.METCase             = real2int(_deliveryNoteQty / factor);
                productTypesTmp.BrokenCase          = real2int(_deliveryNoteQty - (productTypesTmp.METCase * factor));
            }

            productTypesTmp.ProductType                 = whsFilters.Description;
            productTypesTmp.GrossWeight                 = _deliveryNoteQty * salesLine.SalesQty;
            productTypesTmp.ProductTotalWeight          = salesLine.displayMETTotalGrossWeight();
            productTypesTmp.TotalWeight                 = productTypesTmp.ProductTotalWeight + productTypesTmp.PalletContainerTotalWeight;

            while select ContainerTypeCode, ContainerQty from containerTable
                where containerTable.ShipmentId == _shipmentId
            {
                productTypesTmp.PalletContainerTotalWeight += productTypesTmp.ProductTotalWeight * containerTable.ContainerQty;
            }

            productTypesTmp.BundleReportHeaderGuidStr   = bundleHeaderReportGuid;
            productTypesTmp.CoverNotesHeaderGuidStr     = headerReportGuid;;
            productTypesTmp.insert();
        }
    }

    /// <summary>
    /// Add product types for the transfer order.
    /// </summary>
    /// <param name = "_transferId">Transfer order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void addProductTypesTransferOrder(InventTransferId _transferId, MetShipmentId _shipmentId)
    {
        WHSFilters                  whsFilters;
        InventTransferLine          transferLine;
        METInventTransferLine       metTransferLine;
        InventDim                   inventDim;
        MetContainerTable           containerTable;
        METInventItemOrderSetup     metInventItemOrderSetup;
        UnitOfMeasureFromRecId      fromUnit,toUnit;

        while select transferLine where transferLine.TransferId == _transferId
            join metTransferLine
                where metTransferLine.InventTransferLine == transferLine.RecId
            join inventDimId, InventSiteId from inventDim
                where inventDim.inventDimId == transferLine.InventDimId
            join ItemType, FilterCode from metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == transferLine.ItemId
                && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
            join whsFilters
                where whsFilters.FilterTitle == WHSFilterTitle::Code1
                && whsFilters.FilterNum == metInventItemOrderSetup.FilterCode
        {
            Factor                  factor;
            InventDim               inventDimDefaultSetting;
            InventItemSalesSetup    inventItemSalesSetup;

            select firstonly METSalesUnit from inventItemSalesSetup
                join inventDimDefaultSetting
                    where inventDimDefaultSetting.inventDimId == inventItemSalesSetup.InventDimId
                    && inventItemSalesSetup.ItemId == transferLine.ItemId
                    && inventDimDefaultSetting.InventSiteId == inventDim.InventSiteId;

            toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(transferLine.UnitId);
            fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventItemSalesSetup.METSalesUnit);

            factor      = EcoResProductUnitConverter::convertForReleasedProduct(
                                    transferLine.ItemId,
                                    transferLine.inventDimId,
                                    1,
                                    fromUnit,
                                    toUnit,
                                    NoYes::No,
                                    NoYes::No);

            if (factor)
            {
                productTypesTmp.clear();

                productTypesTmp.METCase             = real2int(transferLine.QtyShipped / factor);
                productTypesTmp.BrokenCase          = real2int(transferLine.QtyShipped - (productTypesTmp.METCase * factor));
            }

            while select ContainerTypeCode, ContainerQty from containerTable
                where containerTable.ShipmentId == _shipmentId
            {
                productTypesTmp.PalletContainerTotalWeight += productTypesTmp.ProductTotalWeight * containerTable.ContainerQty;
            }

            productTypesTmp.ProductType                 = whsFilters.Description;
            productTypesTmp.GrossWeight                 = metTransferLine.TOUnitWeight * transferLine.QtyShipped;
            productTypesTmp.ProductTotalWeight          = transferLine.displayMETGrossWeight();
            productTypesTmp.TotalWeight                 = productTypesTmp.ProductTotalWeight + productTypesTmp.PalletContainerTotalWeight;
            productTypesTmp.BundleReportHeaderGuidStr   = bundleHeaderReportGuid;
            productTypesTmp.CoverNotesHeaderGuidStr     = headerReportGuid;;
            productTypesTmp.insert();
        }
    }

/// <summary>
/// productTypesTmp
/// </summary>
/// <returns>METCoverNoteProductTypesTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteProductTypesTmp))]
public METCoverNoteProductTypesTmp getLinesTmp()
{
    select productTypesTmp;
    return productTypesTmp;
}

